CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.company_rule_files FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON kristine.imported_company_rule_models FOR EACH ROW EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.imported_company_rule_models FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER source_guard BEFORE INSERT ON kristine.imported_company_rule_models FOR EACH ROW EXECUTE FUNCTION kristine.guard_company_rule_entry();
