CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.imported_company_rule_seasons FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER source_guard BEFORE INSERT ON kristine.imported_company_rule_seasons FOR EACH ROW EXECUTE FUNCTION kristine.guard_company_rule_entry();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON kristine.imported_company_rule_weekdays FOR EACH ROW EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.imported_company_rule_weekdays FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER source_guard BEFORE INSERT ON kristine.imported_company_rule_weekdays FOR EACH ROW EXECUTE FUNCTION kristine.guard_company_rule_entry();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON kristine.imported_company_rule_blocks FOR EACH ROW EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.imported_company_rule_blocks FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER source_guard BEFORE INSERT ON kristine.imported_company_rule_blocks FOR EACH ROW EXECUTE FUNCTION kristine.guard_company_rule_entry();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON kristine.imported_company_rule_block_rows FOR EACH ROW EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.imported_company_rule_block_rows FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER source_guard BEFORE INSERT ON kristine.imported_company_rule_block_rows FOR EACH ROW EXECUTE FUNCTION kristine.guard_company_rule_entry();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON kristine.imported_company_rule_schedule_days FOR EACH ROW EXECUTE FUNCTION kristine.reject_history_change();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON kristine.imported_company_rule_schedule_days FOR EACH STATEMENT EXECUTE FUNCTION kristine.reject_history_change();
